// PHASE 1 STUB — DO NOT invent a real AWS endpoint.
// The client has not yet supplied the endpoint, method, auth, payload
// shape, headers, or error format for their existing AWS integration.
// This function is the single abstraction point: once those details
// arrive, only this file changes — nothing upstream (engine, UI,
// Catalyst functions calling it) needs to know it happened.

export async function submitApplicationToAWS(applicationData) {
  // eslint-disable-next-line no-console
  console.info('[awsService mock] would submit to AWS:', applicationData);
  await new Promise((resolve) => setTimeout(resolve, 400));
  return {
    ok: true,
    mock: true,
    referenceId: `MOCK-${Date.now()}`,
  };
}

export default { submitApplicationToAWS };
